{"results":[{"id":"R1","verdict":"not_addressed","reason":"onRefund only adds comments and a logger.info call; no HMAC verification before payouts.refund, and the diff shows no signature check anywhere.","quotes":[],"missing":"Actual HMAC comparison of the request signature header against the shared secret, with 401 return before payouts.refund is called.","suggestion":{"summary":"Verify HMAC signature on raw body before issuing refund","code":"export async function onRefund(req: Request, res: Response) {
  const raw = await readRawBody(req);
  const sig = req.header('x-signature') || '';
  const expected = crypto.createHmac('sha256', process.env.REFUND_WEBHOOK_SECRET!)
    .update(raw).digest('hex');
  const sigBuf = Buffer.from(sig, 'utf8');
  const expBuf = Buffer.from(expected, 'utf8');
  if (sigBuf.length !== expBuf.length || !crypto.timingSafeEqual(sigBuf, expBuf)) {
    return res.status(401).end();
  }
  const event = JSON.parse(raw.toString('utf8'));
  await payouts.refund(event.orderId, event.amount);
}"}}]}
